/**
 * @file array.h
 * Project: IFJ26
 *
 * @author Lukáš Pollák (xpollal00)
 * @date 5. 11. 2026
 *
 * @brief Generic dynamic array usable with any element type.
 *
 * An array type is declared once per element type with ARRAY_TYPE. Its
 * elements are accessed directly through the data field (array->data[i]),
 * while growing, inserting and removing are done through the array_* macros,
 * which forward to the type-independent helper functions in array.c.
 *
 * @example
 *  ARRAY_TYPE(IntArray, int);
 *
 *  IntArray* numbers = TRY_MALLOC(sizeof(*numbers));
 *  array_init(numbers);
 *  array_append(ctx, numbers, 42);
 *  array_insert(ctx, numbers, 0, 7);
 *  printf("%d %zu\n", numbers->data[1], numbers->count);  // 42 2
 *  array_free(numbers);
 *  free(numbers);
 */

#ifndef ARRAY_H
#define ARRAY_H

#include <stddef.h>  // size_t, NULL
#include <stdlib.h>  // free
#include "ctx.h"

/**
 * @brief Declares a named dynamic array type holding elements of type T.
 *
 * The declared struct has the following fields:
 *  - data:     pointer to the elements (NULL while capacity is 0)
 *  - count:    number of stored elements
 *  - capacity: number of elements that fit into data without reallocation
 *
 * The fields may be read freely; count and capacity should only be changed
 * through the array_* macros.
 *
 * @param Name Name of the declared type
 * @param T Element type
 */
#define ARRAY_TYPE(Name, T) \
  typedef struct {          \
    T* data;                \
    size_t count;           \
    size_t capacity;        \
  } Name

/**
 * @brief Initializer for an empty array, usable as `IntArray a = ARRAY_EMPTY;`
 */
#define ARRAY_EMPTY {.data = NULL, .count = 0, .capacity = 0}

/**
 * @brief Initializes an array to an empty state without allocating.
 *
 * @param[out] arr Pointer to the array to initialize
 */
#define array_init(arr)  \
  do {                   \
    (arr)->data = NULL;  \
    (arr)->count = 0;    \
    (arr)->capacity = 0; \
  } while (0)

/**
 * @brief Frees the element storage and resets the array to an empty state.
 *
 * Elements themselves are not freed; if they own memory, free it first.
 * The array can be reused afterwards.
 *
 * @param[in,out] arr Pointer to an initialized array
 */
#define array_free(arr) \
  do {                  \
    free((arr)->data);  \
    array_init(arr);    \
  } while (0)

/**
 * @brief Ensures the array can hold at least min_capacity elements.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] arr Pointer to an initialized array
 * @param[in] min_capacity Minimum number of elements to make room for
 */
#define array_reserve(ctx, arr, min_capacity)                               \
  ((arr)->data = array_reserve_helper((ctx), (arr)->data, &(arr)->capacity, \
                                      (min_capacity), sizeof(*(arr)->data)))

/**
 * @brief Appends value to the end of the array, growing it if needed.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] arr Pointer to an initialized array
 * @param[in] value Value to append (assigned, so it must fit the element type)
 *
 * @warning arr is evaluated multiple times.
 */
#define array_append(ctx, arr, value)              \
  do {                                             \
    array_reserve((ctx), (arr), (arr)->count + 1); \
    (arr)->data[(arr)->count++] = (value);         \
  } while (0)

/**
 * @brief Inserts value at index, shifting the following elements right.
 *
 * Throws E_INTERNAL_ERROR if index > count.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] arr Pointer to an initialized array
 * @param[in] index Position of the new element (count appends)
 * @param[in] value Value to insert (assigned, so it must fit the element type)
 *
 * @warning arr is evaluated multiple times and value is evaluated after the
 * elements are shifted, so it must not refer to elements of arr.
 */
#define array_insert(ctx, arr, index, value)                                 \
  do {                                                                       \
    size_t array_insert_index_ = (index);                                    \
    (arr)->data = array_insert_helper((ctx), (arr)->data, &(arr)->count,     \
                                      &(arr)->capacity, array_insert_index_, \
                                      sizeof(*(arr)->data));                 \
    (arr)->data[array_insert_index_] = (value);                              \
  } while (0)

/**
 * @brief Removes the element at index, shifting the following elements left.
 *
 * Throws E_INTERNAL_ERROR if index >= count. Read the element beforehand if it
 * is still needed.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] arr Pointer to an initialized array
 * @param[in] index Position of the element to remove
 */
#define array_remove(ctx, arr, index)                             \
  array_remove_helper((ctx), (arr)->data, &(arr)->count, (index), \
                      sizeof(*(arr)->data))

/**
 * @brief Removes all elements while keeping the allocated storage.
 *
 * @param[in,out] arr Pointer to an initialized array
 */
#define array_clear(arr) ((arr)->count = 0)

/**
 * @brief Grows storage so it fits at least min_capacity elements.
 *
 * Capacity grows geometrically, so repeated appends are amortized O(1).
 * On allocation failure, the storage stays unchanged and the error is thrown.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in] data Current storage, may be NULL when *capacity is 0
 * @param[in,out] capacity Current capacity in elements, updated on growth
 * @param[in] min_capacity Minimum required capacity in elements
 * @param[in] elem_size Size of one element in bytes
 * @return Storage pointer to assign back to the array's data field
 */
void* array_reserve_helper(Ctx* ctx,
                           void* data,
                           size_t* capacity,
                           size_t min_capacity,
                           size_t elem_size);

/**
 * @brief Makes room for one element at index by shifting the tail right.
 *
 * Increments *count; the slot at index is left for the caller to fill.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in] data Current storage, may be NULL when *capacity is 0
 * @param[in,out] count Number of stored elements
 * @param[in,out] capacity Current capacity in elements
 * @param[in] index Position of the new slot, must be <= *count
 * @param[in] elem_size Size of one element in bytes
 * @return Storage pointer to assign back to the array's data field
 */
void* array_insert_helper(Ctx* ctx,
                          void* data,
                          size_t* count,
                          size_t* capacity,
                          size_t index,
                          size_t elem_size);

/**
 * @brief Removes the element at index by shifting the tail left.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] data Current storage
 * @param[in,out] count Number of stored elements, decremented on success
 * @param[in] index Position of the element to remove, must be < *count
 * @param[in] elem_size Size of one element in bytes
 */
void array_remove_helper(Ctx* ctx,
                         void* data,
                         size_t* count,
                         size_t index,
                         size_t elem_size);

#endif
